/*
 * MST_$PRIV_SET_TOUCH_AHEAD_CNT - set the touch-ahead count of the segments
 * covering [*va_ptr, *va_ptr + *length_ptr)
 *
 * Original address: 0x00E44514 (SAU2 map)
 * Size: 480 bytes (0x00E44514 .. 0x00E446FB)
 * Generated by: Claude Opus 5.5
 *
 * Only caller: MST_$SET_TOUCH_AHEAD_CNT (0x00E44720) with flags = &0.
 * A5 = 0xE7CF0C (MST_UNWIRED) is loaded but not used.
 *
 * Frame (link.w A6,-0x20): (0x8) flags (D3; `tst.b (A0)` reads its first
 * byte, i.e. bit 15 of the word: "privileged"), (0xc) va_ptr (A2), (0x10)
 * length_ptr, (0x14) count_ptr, (0x18) result_ptr (the old count, a word),
 * (0x1c) status (A3); (-0x20) segment base, (-0x14) segment number,
 * (-0x10) the count to store (its low byte is (-0xf)), (-0x4) status.
 *
 * Blocks:
 *   0x00E44532-0x00E44580  count: -4 -> 1, -3 -> 0x20, -2 -> MST_$TOUCH_COUNT,
 *                          -1 -> -1 ("read only") via the jump table at
 *                          0x00E44546 (00 22 00 1a 00 10 00 08); anything
 *                          else is clamped to 1..0x20 (signed bge, then
 *                          unsigned bls)
 *   0x00E44584-0x00E4459E  D2 = MST_$VA_TO_SEGNO(*va, &seg, PROC1_$AS_ID)
 *                          (the asid of a private segment, 0 for global)
 *   0x00E445A2-0x00E445E6  D2 > 0x39 -> illegal address.  The last segment
 *                          allowed: private: seg < MST_$PRIVATE_A_SIZE ->
 *                          that - 1, else (privileged only) MST_$SEG_TN - 1;
 *                          global: seg < MST_$GLOBAL_A_SIZE -> that - 1, else
 *                          (privileged only) MST_$SEG_TN, with no - 1
 *   0x00E445E8-0x00E4461E  last = seg + ((*va & 0x7FFF) + *len - 1) >> 15;
 *                          beyond the limit (unsigned) -> illegal address,
 *                          returned without touching the result
 *   0x00E44622-0x00E44674  ML_$LOCK(0xC); every MST page-table word for the
 *                          segment groups seg>>6 .. last>>6 must be set, else
 *                          status = illegal address
 *   0x00E44678-0x00E446D8  for each segment: D2 = old count (bits 2..6 of
 *                          the MSTE location byte, + 1); count -1 stops after
 *                          the first read; else store (count - 1) << 2
 *   0x00E446DC-0x00E446EE  ML_$UNLOCK(0xC); *result = D2w; *status
 *
 * Quirk kept: when the page check fails, or the range is empty, D2 still
 * holds the MST index of the first group (0x00E44642-0x00E4464C), and that
 * is what *result receives.
 */

#include "mst/mst_internal.h"

/* The MSTE location byte (+0x0C) of ASID-relative segment `seg`:
 * 0xEF6400 + MST[(seg >> 6) + base] * 0x400 + (seg & 0x3F) * 0x10 - 0x3F4
 * (0x00E44690-0x00E446B4). */
static mste_t *mst_$touch_mste(uint16_t asid_base, uint16_t seg)
{
    uint16_t page = MST[(uint16_t)((seg >> 6) + asid_base)];

    return (mste_t *)ARCH_VA_TO_PTR(MST_PAGE_TABLE_BASE + (uint32_t)page * 0x400u +
                                    (uint32_t)(seg & 0x3F) * 0x10u - 0x400u);
}

void MST_$PRIV_SET_TOUCH_AHEAD_CNT(uint16_t *flags, uint32_t *va_ptr,
                                   uint32_t *length_ptr, int16_t *count_ptr,
                                   void *result_ptr, status_$t *status)
{
    int16_t count;          /* (-0x10,A6) */
    uint16_t seg;           /* (-0x14,A6), D4w */
    uint16_t asid;          /* D2w on return from MST_$VA_TO_SEGNO */
    uint16_t limit;         /* D0w */
    uint16_t extra;         /* D1w */
    uint16_t last;          /* D5w */
    uint16_t base;          /* D3w */
    uint16_t d2;            /* D2w */
    int16_t n;              /* D0w / D1w loop counters */
    uint16_t idx;
    status_$t st;           /* (-0x4,A6) */
    int privileged = (int8_t)(*flags >> 8) < 0;
    mste_t *e;
    uint8_t hi;

    /* 0x00E44532-0x00E44580 */
    switch (*count_ptr) {
    case -4: count = 1;                 break;  /* 0x00E44568 */
    case -3: count = 0x20;              break;  /* 0x00E44560 */
    case -2: count = (int16_t)MST_$TOUCH_COUNT; break;  /* 0x00E44556 */
    case -1: count = -1;                break;  /* 0x00E4454E */
    default:
        /* 0x00E44570-0x00E44580 */
        count = 1;
        if (count < *count_ptr) {
            count = *count_ptr;
        }
        if ((uint16_t)count > 0x20) {
            count = 0x20;
        }
        break;
    }

    /* 0x00E44584-0x00E4459E */
    asid = MST_$VA_TO_SEGNO(*va_ptr, &seg, PROC1_$AS_ID);
    d2 = asid;

    /* 0x00E445A2-0x00E445E6 */
    if (asid > 0x39) {
        goto illegal;
    }
    if (asid != 0) {
        if (seg < MST_$PRIVATE_A_SIZE) {
            limit = (uint16_t)(MST_$PRIVATE_A_SIZE - 1);
        } else {
            if (!privileged) {
                goto illegal;
            }
            limit = (uint16_t)(MST_$SEG_TN - 1);
        }
    } else {
        if (seg < MST_$GLOBAL_A_SIZE) {
            limit = (uint16_t)(MST_$GLOBAL_A_SIZE - 1);
        } else {
            if (!privileged) {
                goto illegal;
            }
            limit = MST_$SEG_TN;                /* 0x00E445E2: no - 1 */
        }
    }

    /* 0x00E445E8-0x00E44616 */
    extra = (uint16_t)(((*va_ptr - (*va_ptr & 0xFFFF8000u)) + *length_ptr - 1)
                       >> 15);
    if ((uint32_t)seg + (uint32_t)extra > (uint32_t)limit) {
        goto illegal;
    }

    /* 0x00E44622-0x00E44634 */
    last = (uint16_t)(extra + seg);
    ML_$LOCK(ML_LOCK_MST_ASID);
    st = status_$ok;

    /* 0x00E44638-0x00E44674 */
    base = MST_ASID_BASE[asid];
    d2 = (uint16_t)((seg >> 6) + base);
    n = (int16_t)(((last >> 6) + base) - d2);
    if (n >= 0) {
        idx = d2;
        do {
            if (MST[idx] == 0) {
                st = status_$reference_to_illegal_address;  /* 0x00E44668 */
                goto unlock;
            }
            idx++;
        } while (--n != -1);
    }

    /* 0x00E44678-0x00E446D8 */
    n = (int16_t)(last - seg);
    if (n >= 0) {
        do {
            e = mst_$touch_mste(base, seg);
            hi = (uint8_t)(e->location >> 24);
            d2 = (uint16_t)(((hi & 0x7C) >> 2) + 1);
            if (count == -1) {
                break;                              /* 0x00E446C2 */
            }
            /* 0x00E446C4-0x00E446D2: (-0xf,A6) is the count's low byte */
            hi &= 0x83;
            hi |= (uint8_t)((uint8_t)((uint8_t)count - 1) << 2) & 0x7C;
            e->location = (e->location & 0x00FFFFFFu) | ((uint32_t)hi << 24);
            seg++;
        } while (--n != -1);
    }

unlock:
    /* 0x00E446DC-0x00E446EE */
    ML_$UNLOCK(ML_LOCK_MST_ASID);
    *(uint16_t *)result_ptr = d2;
    *status = st;
    return;

illegal:
    /* 0x00E44618 */
    *status = status_$reference_to_illegal_address;
}
